def pieces(n, one, many):
    return 1 if n <= one else -(-n // many)
def segments(text):
    if all(c in GSM for c in text):
        return 'GSM-7', len(text), pieces(len(text), 160, 153)
    units = len(text.encode('utf-16-le')) // 2
    return 'UCS-2', units, pieces(units, 70, 67)
for text in ('Hello, world!', 'a' * 161, 'Yedekleme tamamlandi',
             'Yedekleme tamamlandı'):
    print(len(text), segments(text))

import hmac, subprocess, sys
SECRET = 'correct horse'
ALLOWED = {'hello': [sys.executable, '-c', 'print("hello")']}
def handle(password, name):
    if not hmac.compare_digest(password, SECRET):
        return 'wrong password'
    if name not in ALLOWED:
        return 'not allowed'
    done = subprocess.run(ALLOWED[name], capture_output=True, text=True)
    return f'ran {name}, printed {done.stdout!r}'
mails = (('x', 'hello'), (SECRET, 'rm -rf /'), (SECRET, 'hello'))
for password, name in mails:
    print(handle(password, name))
